local config = {
  ui_story_5041_50410101_1_dialog_content = "¡Luke, hay un paquete para ti!",
  ui_story_5041_50410101_2_dialog_content = "PlayerName? ¿Por qué estás entregando?",
  ui_story_5041_50410101_3_dialog_content = "¿Y quien es este?",
  ui_story_5041_50410101_4_dialog_content = "Esta es Lady Jeriah de Courier Union. Solo estoy ayudando en el Día de la Corona de Luna.",
  ui_story_5041_50410101_5_dialog_content = "Hola, Subcomandante de los Mercenarios de la Llama Blanca. Tu reputación te precede.",
  ui_story_5041_50410101_6_dialog_content = "¿Un miembro de alto rango del Sindicato de Mensajeros? Un honor conocerte. ¿Pero quién me enviaría un paquete?",
  ui_story_5041_50410101_7_dialog_content = "¿Por qué no lo abres? ¿Deberíamos darte algo de privacidad?",
  ui_story_5041_50410101_8_dialog_content = "No hay necesidad. Si resulta ser una amenaza de un némesis, necesitaré más información de usted.",
  ui_story_5041_50410101_9_dialog_content = "¿No eres demasiado cauteloso? Un empaque tan suave no podría ser de un rival.",
  ui_story_5041_50410101_10_dialog_content = "Hmm, hay una nota adjunta dentro de la caja.",
  ui_story_5041_50410101_11_dialog_content = "\"Comandante Luke, lamento comunicarme con usted de esta manera, pero la misión es lo primero, por lo que debemos confiar en la correspondencia\".",
  ui_story_5041_50410101_12_dialog_content = "\"Todos hemos sido testigos de primera mano de su sentido del deber hacia los Mercenarios de la Llama Blanca y su consideración por todos\".",
  ui_story_5041_50410101_13_dialog_content = "\"Todo lo que hacemos es llevar a cabo las misiones, pero debes pensar en el futuro de la organización y cómo expandirla...\"",
  ui_story_5041_50410101_14_dialog_content = "\"También te preocupas por el bienestar de cada miembro hasta el último detalle. A menudo bromeamos y decimos que eres omnipotente\".",
  ui_story_5041_50410101_15_dialog_content = "\"Sin embargo, sé que también eres una persona normal, y cargar tanto durante tanto tiempo te cansa a veces\".",
  ui_story_5041_50410101_16_dialog_content = "Es de ellos... Les dije que no me llamaran \"comandante\". No puedo creer que se hayan tomado el tiempo para escribir esto en medio de una misión.",
  ui_story_5041_50410101_17_dialog_content = "Eso es muy conmovedor. Supongo que tus mercenarios se preocupan mucho por ti.",
  ui_story_5041_50410101_18_dialog_content = "Eso es porque Luke es una persona muy responsable, un hecho obvio para todos.",
  ui_story_5041_50410101_19_dialog_content = "¿Qué más dice la carta?",
  ui_story_5041_50410101_20_dialog_content = "\"Te levantas temprano y te acuestas tarde todas las noches, así que nos tomamos el tiempo para hacerte una bolsa de hierbas\".",
  ui_story_5041_50410101_21_dialog_content = "\"Escuchamos que estas hierbas pueden ayudar a dormir. Pruébelas la próxima vez que duerma colocándolas junto a su almohada\".",
  ui_story_5041_50410101_22_dialog_content = "\"Esperamos que también puedas echarte una siesta de vez en cuando\".",
  ui_story_5041_50410101_23_dialog_content = "\"De tus mercenarios\".",
  ui_story_5041_50410101_24_dialog_content = "Hacer todo esto en una misión... Realmente solo estaba haciendo lo que se suponía que debía hacer.",
  ui_story_5041_50410101_25_dialog_content = "Ciertamente no esperaba esto.",
  ui_story_5041_50410101_26_dialog_content = "Sí, Luke, deberías tomártelo con calma de vez en cuando. Eres propenso a cometer errores si siempre estás tenso como un cable.",
  ui_story_5041_50410101_27_dialog_content = "El descanso adecuado es fundamental para completar cada nueva tarea que se nos presente... Creo que tienen razón.",
  ui_story_5041_50410101_28_dialog_content = "Dado que todo el mundo parece estar diciendo lo mismo, tomaré el consejo.",
  ui_story_5041_50410101_29_dialog_content = "Una vez que termine hoy, tomaré una siesta con la bolsa al lado de mi almohada.",
  ui_story_5041_50410201_1_dialog_content = "Huff, huff... ¡Ahí está, Comandante Hiiro!",
  ui_story_5041_50410201_2_dialog_content = "¿PlayerName?",
  ui_story_5041_50410201_3_dialog_content = "¿Qué estás haciendo aquí? ¿Pasó algo en Illumina?",
  ui_story_5041_50410201_4_dialog_content = "No, solo estoy entregando correo con Jeriah de Courier Union. Aquí, un paquete para ti, uno bastante fuerte también.",
  ui_story_5041_50410201_5_dialog_content = "Je, creo que el remitente es interesante.",
  ui_story_5041_50410201_6_dialog_content = "Extraño, ¿quién me enviaría un paquete hasta aquí en la línea del frente?",
  ui_story_5041_50410201_7_dialog_content = "Eso es normal. Después de todo, es el Día de la Corona de la Luna.",
  ui_story_5041_50410201_8_dialog_content = "¿Día de la corona de luna? Ah, cierto... Lo olvidé por completo.",
  ui_story_5041_50410201_9_dialog_content = "Tengo poco tiempo, así que veamos qué hay dentro... Espera, déjame ver quién lo envió primero.",
  ui_story_5041_50410201_10_dialog_content = "Oh, es de Zoya. Estos son...",
  ui_story_5041_50410201_11_dialog_content = "Bollos de aserrín, carne enlatada, crema de champiñones, frijoles con chocolate e incluso rollos de canela.",
  ui_story_5041_50410201_12_dialog_content = "Todas son especialidades de Illumina.",
  ui_story_5041_50410201_13_dialog_content = "Creo que es una tradición para los enamorados en Illumina regalar rollos de canela hechos a mano. Muy romántico.",
  ui_story_5041_50410201_14_dialog_content = "Probablemente no fue intencional por parte de Zoya.",
  ui_story_5041_50410201_15_dialog_content = "(De alguna manera, no creo que haya sido involuntario).",
  ui_story_5041_50410201_16_dialog_content = "Creo que hay algo escrito en la caja.",
  ui_story_5041_50410201_17_dialog_content = "\"Lady Hiiro, ¡gracias por su trabajo en primera línea! Escuché que estaría fuera por mucho tiempo esta vez. Solo puedo imaginar lo agotador que será\".",
  ui_story_5041_50410201_18_dialog_content = "\"Me imagino que estarás deseando las delicias de Illumina, así que le pedí a la abuela que preparara un paquete de atención\".",
  ui_story_5041_50410201_19_dialog_content = "\"Pero yo mismo hice los rollos de canela, ¡así que asegúrate de probarlos primero!\"",
  ui_story_5041_50410201_20_dialog_content = "(Me imagino la mirada en el rostro de Zoya.)",
  ui_story_5041_50410201_21_dialog_content = "\"Lady Hiiro, me encantaría pasar el Día de la Corona de la Luna contigo, pero la primera línea es la prioridad, ¡así que por favor cuídate!\"",
  ui_story_5041_50410201_22_dialog_content = "\"¡Mi corazón y mi alma te pertenecen, mi bella, fuerte y genial Lady Hiiro!\"",
  ui_story_5041_50410201_23_dialog_content = "Una persona que puede leer una oración como esa en voz alta con una cara seria es realmente extraordinaria.",
  ui_story_5041_50410201_24_dialog_content = "Ahaha, estoy de acuerdo.",
  ui_story_5041_50410201_25_dialog_content = "Aprecio los pensamientos de Zoya, y ciertamente extraño la comida de Illumina.",
  ui_story_5041_50410201_26_dialog_content = "Ella siempre es tan cariñosa. Estoy seguro de que a todos en el laboratorio de investigación también les gusta.",
  ui_story_5041_50410201_27_dialog_content = "Creo que ella solo se preocupa por ti...",
  ui_story_5041_50410201_28_dialog_content = "Ya que ella misma hizo los rollos de canela, le daré un mordisco.",
  ui_story_5041_50410201_29_dialog_content = "*mastica*",
  ui_story_5041_50410201_30_dialog_content = "Mm. Realmente puedo saborear los sentimientos de Zoya a partir de esto.",
  ui_story_5041_50410201_31_dialog_content = "(Voy a garantizar una conjetura que tiene un sabor muy cuestionable...)",
  ui_story_5041_50410201_32_dialog_content = "Gracias por llevar esto a la primera línea. ¿Por qué no se quedan ustedes dos a pasar la noche? Podemos deleitarnos con esta comida juntos.",
  ui_story_5041_50410201_33_dialog_content = "Claro, estoy bastante interesado en la tarifa de Illumina.",
  ui_story_5041_50410201_34_dialog_content = "¡Oye, todavía tenemos más correo para entregar!",
  ui_story_5041_50410301_1_dialog_content = "¡Novio, tengo un paquete para ti!",
  ui_story_5041_50410301_2_dialog_content = "Primero fuimos al Palacio de Invierno, pero, sorprendentemente, no estabas allí.",
  ui_story_5041_50410301_3_dialog_content = "Solo estoy aquí dando un paseo. No esperaba que fueras el mensajero, PlayerName.",
  ui_story_5041_50410301_4_dialog_content = "Vine con Jeriah, así que solo estoy ayudando.",
  ui_story_5041_50410301_5_dialog_content = "El paisaje en Northland siempre es espectacular, no importa cuántas veces haya estado aquí.",
  ui_story_5041_50410301_6_dialog_content = "Está aislado del resto del continente, casi en su propio mundo. Espero que te guste aquí.",
  ui_story_5041_50410301_7_dialog_content = "Ah, sí, aquí está tu paquete. ¡Es de Lola!",
  ui_story_5041_50410301_8_dialog_content = "¿Lola? Si no recuerdo mal, últimamente no ha estado en Northland.",
  ui_story_5041_50410301_9_dialog_content = "Ella parece haber visitado muchos lugares. Sus mejillas estaban todas rojas por la emoción.",
  ui_story_5041_50410301_10_dialog_content = "Dada su personalidad, probablemente se divirtió mucho disfrutando de los bocadillos y chucherías locales.",
  ui_story_5041_50410301_11_dialog_content = "De todos modos, déjame echar un vistazo dentro...",
  ui_story_5041_50410301_12_dialog_content = "¿Chocolate con forma de eclipse?",
  ui_story_5041_50410301_13_dialog_content = "Eso se ve bastante... auténtico.",
  ui_story_5041_50410301_14_dialog_content = "También hay una nota.",
  ui_story_5041_50410301_15_dialog_content = "\"Novio, mira este chocolate con sabor a Eclipsite que encontré en una tienda de dulces Umbraton. ¡Debes probarlo!\"",
  ui_story_5041_50410301_16_dialog_content = "Me cuesta imaginar cómo sabrían los Eclipsites.",
  ui_story_5041_50410301_17_dialog_content = "Bueno, siempre hay una primera para todo.",
  ui_story_5041_50410301_18_dialog_content = "Y lo que hay en esta caja negra... ¡Guau!",
  ui_story_5041_50410301_19_dialog_content = "¿Estás bien, Novio?",
  ui_story_5041_50410301_20_dialog_content = "¿Es este uno de esos juguetes sorpresa? Eso me asustó.",
  ui_story_5041_50410301_21_dialog_content = "Esta cabeza recuerda un poco a cierta persona...",
  ui_story_5041_50410301_22_dialog_content = "¿Soy solo yo o se parece a Sinsa?",
  ui_story_5041_50410301_23_dialog_content = "Es un diseño divertido, pero debería guardarlo.",
  ui_story_5041_50410301_24_dialog_content = "\"Me encontré con una subasta en un mercado del desierto y no podía creer que nadie pujara por este juguete genial, ¡así que lo compré!\"",
  ui_story_5041_50410301_25_dialog_content = "\"Creo que está inspirado en alguien, pero no tengo idea de quién\".",
  ui_story_5041_50410301_26_dialog_content = "Ni siquiera sabía que esos mercados vendían estas cosas. Que único.",
  ui_story_5041_50410301_27_dialog_content = "Se ajusta al estilo de Lola, de acuerdo.",
  ui_story_5041_50410301_28_dialog_content = "Esperemos que no haya más sorpresas en esta caja... ¿Son flores secas?",
  ui_story_5041_50410301_29_dialog_content = "son tan bonitos...",
  ui_story_5041_50410301_30_dialog_content = "\"Los recolecté durante mi viaje. Incluyen mis rosas silvestres favoritas y algunas otras que no reconozco\".",
  ui_story_5041_50410301_31_dialog_content = "\"Los presioné en marcadores. Te gusta leer, ¡así que creo que los encontrarás útiles!\"",
  ui_story_5041_50410301_32_dialog_content = "\"¡Si averiguaste qué flores son, házmelo saber!\"",
  ui_story_5041_50410301_33_dialog_content = "Es un espíritu tan libre... Y todas las flores son impresionantes.",
  ui_story_5041_50410301_34_dialog_content = "Creo que estos son amaranto, lirio de palma y jazmín. Supongo que tendré que escribirle y decírselo.",
  ui_story_5041_50410301_35_dialog_content = "Muchas gracias a los dos por entregar el paquete. ¿Te gustaría probar el chocolate conmigo?",
  ui_story_5041_50410301_36_dialog_content = "(¿Chocolate con sabor a eclipse? Creo que pasaré).",
  ui_story_5041_50410301_37_dialog_content = "Muchas gracias.",
  ui_story_5041_50410301_38_dialog_content = "¡Oye, no comas nada!",
  ui_story_5041_50410401_1_dialog_content = "Esta debería ser la dirección... ¿probablemente?",
  ui_story_5041_50410401_2_dialog_content = "¡La escritura es tan ilegible que casi me duelen los ojos al leer!",
  ui_story_5041_50410401_3_dialog_content = "Apenas puedo decir que está dirigido a Harbor City, pero el resto es un revoltijo...",
  ui_story_5041_50410401_4_dialog_content = "¿Estamos incluso en el lugar correcto?",
  ui_story_5041_50410401_5_dialog_content = "Sí, este es el lugar correcto.",
  ui_story_5041_50410401_6_dialog_content = "¿Cómo estás tan seguro, Jeriah?",
  ui_story_5041_50410401_7_dialog_content = "Mira allí, ¿no parece que esa persona está esperando el correo?",
  ui_story_5041_50410401_8_dialog_content = "Suspiro, ¿estará aquí hoy? estoy un poco cansada...",
  ui_story_5041_50410401_9_dialog_content = "¡¿Cuándo diablos llegó allí?! ¡No la vi allí antes!",
  ui_story_5041_50410401_10_dialog_content = "¿Estás hablando de mí?",
  ui_story_5041_50410401_11_dialog_content = "He estado aquí todo el tiempo, pero no me he movido porque estoy demasiado cansada.",
  ui_story_5041_50410401_12_dialog_content = "No me extraña que no te vi...",
  ui_story_5041_50410401_13_dialog_content = "¿Ustedes son los mensajeros?",
  ui_story_5041_50410401_14_dialog_content = "Sí, lo somos, jovencita.",
  ui_story_5041_50410401_15_dialog_content = "Esto va dirigido a Ni... ¿Nina?",
  ui_story_5041_50410401_16_dialog_content = "es tina T, na.",
  ui_story_5041_50410401_17_dialog_content = "¿No me digas que olvidaste mi nombre?",
  ui_story_5041_50410401_18_option_content = "¡Te conozco!",
  ui_story_5041_50410401_19_dialog_content = "Tú eras el que buscaba obtener sellos de Jeriah en Lumopolis, ¿verdad?",
  ui_story_5041_50410401_20_dialog_content = "Me recuerdas.",
  ui_story_5041_50410401_21_dialog_content = "Por supuesto, tengo una mente como una trampa de acero.",
  ui_story_5041_50410401_22_option_content = "No estoy seguro...",
  ui_story_5041_50410401_23_dialog_content = "Entonces déjame presentarme.",
  ui_story_5041_50410401_24_dialog_content = "Soy la jueza Tina del Salón de Justicia de Lumopolis. Estoy en Harbor City ahora por asuntos oficiales.",
  ui_story_5041_50410401_25_dialog_content = "¿Puedo preguntar si esto es para mí?",
  ui_story_5041_50410401_26_dialog_content = "Parece que dice que el nombre del destinatario es Tina.",
  ui_story_5041_50410401_27_dialog_content = "Lo siento, la escritura es demasiado difícil de distinguir.",
  ui_story_5041_50410401_28_dialog_content = "No esperaba ver a alguien del Lumo Hall of Justice en Harbor City.",
  ui_story_5041_50410401_29_dialog_content = "Fue un viaje largo, pero dormir en un dirigible fue toda una experiencia.",
  ui_story_5041_50410401_30_dialog_content = "El barco se mecía suavemente con el viento, y la cama blanda era como una cuna.",
  ui_story_5041_50410401_31_dialog_content = "¡Conozco ese sentimiento! Es como cuando me acuesto en el Coloso mientras está en el aire.",
  ui_story_5041_50410401_32_dialog_content = "Tienes buen gusto.",
  ui_story_5041_50410401_33_dialog_content = "A juzgar por tu atuendo, ¿debes ser el que llamaron Navegante del Coloso? ¿La última Caelestita?",
  ui_story_5041_50410401_34_dialog_content = "Er... mis títulos parecen volverse más elegantes...",
  ui_story_5041_50410401_35_dialog_content = "¿Por qué no me presento?",
  ui_story_5041_50410401_36_dialog_content = "De hecho, soy un Caelestite, pero solo un Caelestite normal.",
  ui_story_5041_50410401_37_dialog_content = "Solo llamame PlayerName!",
  ui_story_5041_50410401_38_dialog_content = "PlayerName? Hmm, ese es un nombre interesante.",
  ui_story_5041_50410401_39_dialog_content = "Estoy ayudando a Courier Union a entregar el correo ahora mismo. Conmigo aquí está Jeriah.",
  ui_story_5041_50410401_40_dialog_content = "¡Hola!",
  ui_story_5041_50410401_41_dialog_content = "Qué adorable jovencita eres.",
  ui_story_5041_50410401_42_dialog_content = "De todos modos, por favor firme aquí!",
  ui_story_5041_50410401_43_dialog_content = "Hmm, ¿podría ser esto \"eso\"...?",
  ui_story_5041_50410401_44_dialog_content = "<color=#e8d9bb>*firmar*</color>",
  ui_story_5041_50410401_45_dialog_content = "\"Eso\"?",
  ui_story_5041_50410401_46_dialog_content = "Algo que he estado esperando todo este tiempo, desde que le escribí a ese tipo.",
  ui_story_5041_50410401_47_dialog_content = "Bueno, déjame averiguarlo con seguridad...",
  ui_story_5041_50410401_48_dialog_content = "<color=#e8d9bb>Rotura-</color>",
  ui_story_5041_50410401_49_dialog_content = "¿Ah?",
  ui_story_5041_50410401_50_dialog_content = "Mmm...",
  ui_story_5041_50410401_51_dialog_content = "¿Una bolsa de hojas? Y dos frutos silvestres que pueden o no ser comestibles...",
  ui_story_5041_50410401_52_dialog_content = "E-Las hojas están podridas... No se dañaron en el tránsito, ¿verdad?",
  ui_story_5041_50410401_53_dialog_content = "PlayerName, ¿comprobó el estado del paquete cuando lo recibió?",
  ui_story_5041_50410401_54_dialog_content = "No...",
  ui_story_5041_50410401_55_dialog_content = "Vi este paquete en mi puerta cuando salí esta mañana.",
  ui_story_5041_50410401_56_dialog_content = "Cuando miré y vi que no era para mí, lo traté como un paquete esperando ser entregado y lo traje conmigo.",
  ui_story_5041_50410401_57_dialog_content = "Así no es como funciona, Caelestite.",
  ui_story_5041_50410401_58_dialog_content = "Debe verificar el estado del contenido cuando recibe un paquete para saber qué tipo de precauciones son necesarias para entregarlo.",
  ui_story_5041_50410401_59_dialog_content = "Es una parte básica de ser un mensajero.",
  ui_story_5041_50410401_60_dialog_content = "Lo siento...",
  ui_story_5041_50410401_61_dialog_content = "¿De qué estás hablando?",
  ui_story_5041_50410401_62_dialog_content = "Estas hojas no están dañadas.",
  ui_story_5041_50410401_63_dialog_content = "¿No lo son?",
  ui_story_5041_50410401_64_dialog_content = "¿Ves esto en la hoja? ¿No se parece a Universese?",
  ui_story_5041_50410401_65_dialog_content = "¡Sí, ahora que lo mencionas!",
  ui_story_5041_50410401_66_dialog_content = "Pero está tan torcido que casi no lo reconozco.",
  ui_story_5041_50410401_67_dialog_content = "Creo que se lee, \"Gracias\"?",
  ui_story_5041_50410401_68_dialog_content = "Estas no son hojas ordinarias. Son papel de carta.",
  ui_story_5041_50410401_69_dialog_content = "Si bien estoy eufórico por conseguir esto, es bastante desafortunado.",
  ui_story_5041_50410401_70_dialog_content = "Las hojas están en orden aleatorio y la escritura es imposible de descifrar...",
  ui_story_5041_50410401_71_dialog_content = "Incluso yo no puedo descifrar todo en ellos...",
  ui_story_5041_50410401_72_dialog_content = "Es tan triste que no llegaré a saber lo que el pequeño amigo quería decir.",
  ui_story_5041_50410401_73_dialog_content = "Pero se siente bien recibir una respuesta, de todos modos.",
  ui_story_5041_50410401_74_dialog_content = "Gracias a ambos por entregarlo.",
  ui_story_5041_50410401_75_dialog_content = "¿Quién es el tipo pequeño del que sigues hablando?",
  ui_story_5041_50410401_76_dialog_content = "Suena como un hermano o hermana pequeña.",
  ui_story_5041_50410401_77_dialog_content = "Sí, podrías llamarlos así.",
  ui_story_5041_50410401_78_dialog_content = "Ese tipo es tan lindo como un gatito y te dan ganas de abrazarlo.",
  ui_story_5041_50410401_79_dialog_content = "¿Es un animal pequeño?",
  ui_story_5041_50410401_80_dialog_content = "Es un secreto.",
  ui_story_5041_50410401_81_dialog_content = "Está bien, no voy a entrometerme. Tienes derecho a tu privacidad, después de todo.",
  ui_story_5041_50410401_82_dialog_content = "Gracias por elegir Courier Union. ¡Esperamos poder servirle la próxima vez!",
  ui_story_5041_50410401_83_dialog_content = "Asegúrese de confirmar la condición de cualquier paquete que entregue también.",
  ui_story_5041_50410401_84_dialog_content = "Si...",
  ui_story_5041_50410501_1_dialog_content = "¡Aquí estás, Eva!",
  ui_story_5041_50410501_2_dialog_content = "Eres tu, PlayerName! ¿Y quien es este?",
  ui_story_5041_50410501_3_dialog_content = "Hola, jovencita, soy Jeriah de Courier Union.",
  ui_story_5041_50410501_4_dialog_content = "Ah, un mensajero. Nunca he visto a nadie de la Unión antes.",
  ui_story_5041_50410501_5_dialog_content = "¡Hola, soy Eva!",
  ui_story_5041_50410501_6_dialog_content = "¡Tienes correo, Eve!",
  ui_story_5041_50410501_7_dialog_content = "Es de Sinsa.",
  ui_story_5041_50410501_8_dialog_content = "¿Mi hermano? Me pregunto qué me envió.",
  ui_story_5041_50410501_9_dialog_content = "Probablemente algo muy importante.",
  ui_story_5041_50410501_10_dialog_content = "Esto fue lo que dijo cuando nos entregó el paquete...",
  ui_story_5041_50410501_11_dialog_content = "Esta es una entrega urgente para Eve. ¡Asegúrate de que lo consiga! ¿Entiendo?",
  ui_story_5041_50410501_12_dialog_content = "¡Lo tengo!",
  ui_story_5041_50410501_13_dialog_content = "Es la primera vez que está sola fuera de casa. Debo garantizar su seguridad y mantenerla alejada de los malos.",
  ui_story_5041_50410501_14_dialog_content = "Estaría justo a su lado ahora mismo, protegiéndola de todo peligro si no se hubiera negado a dejarme acompañar.",
  ui_story_5041_50410501_15_dialog_content = "¿Eva fue a alguna parte? ¿A dónde fue?",
  ui_story_5041_50410501_16_dialog_content = "Una base ubicada a varios cientos de metros de distancia.",
  ui_story_5041_50410501_17_dialog_content = "Seguro que está lejos...",
  ui_story_5041_50410501_18_dialog_content = "¡Por supuesto que es! ¡Solo asegúrate de que reciba este paquete tan importante!",
  ui_story_5041_50410501_19_dialog_content = "Suspiro... Todavía es tan sobreprotector.",
  ui_story_5041_50410501_20_dialog_content = "Solo quería experimentar salir por mi cuenta...",
  ui_story_5041_50410501_21_dialog_content = "Bueno, creo que es una bendición disfrazada tener a alguien en la familia cuidando de ti todo el tiempo.",
  ui_story_5041_50410501_22_dialog_content = "¡Sí!",
  ui_story_5041_50410501_23_dialog_content = "Déjame ver lo que me envió mi hermano.",
  ui_story_5041_50410501_24_dialog_content = "Un cuaderno, y... ¿para qué se supone que sirve esta barra curva?",
  ui_story_5041_50410501_25_dialog_content = "Hasta donde yo sé, es una palanca.",
  ui_story_5041_50410501_26_dialog_content = "Puede levantar cosas pesadas con él y usarlo para defensa propia en caso de apuro.",
  ui_story_5041_50410501_27_dialog_content = "No me digas que Sinsa quiere que lo uses como arma defensiva...",
  ui_story_5041_50410501_28_dialog_content = "Eso suena como él...",
  ui_story_5041_50410501_29_dialog_content = "Leeré lo que hay en el cuaderno.",
  ui_story_5041_50410501_30_dialog_content = "¿\"Para Eve: Nunca salgas con esta gente\"?",
  ui_story_5041_50410501_31_dialog_content = "¡Es una larga lista de nombres!",
  ui_story_5041_50410501_32_dialog_content = "¿Por qué suena como una lista negra?",
  ui_story_5041_50410501_33_dialog_content = "¿Quién está en eso?",
  ui_story_5041_50410501_34_dialog_content = "Déjame ver... El juez de Lumopolis con colmillos de tiburón.",
  ui_story_5041_50410501_35_dialog_content = "Un investigador de Illumina apodado el \"Hombre de mediana edad\".",
  ui_story_5041_50410501_36_dialog_content = "Un comerciante de Umbraton que siempre está sonriendo.",
  ui_story_5041_50410501_37_dialog_content = "¿Y La Última Caelestita que corretea con el Coloso?",
  ui_story_5041_50410501_38_option_content = "¡Oye, ese soy yo!",
  ui_story_5041_50410501_39_dialog_content = "¿Por qué Sinsa me llama malo...?",
  ui_story_5041_50410501_40_dialog_content = "Esto es lo que escribió...",
  ui_story_5041_50410501_41_dialog_content = "\"PlayerName no es una mala persona, pero hay una cosa que debes tener en cuenta...\"",
  ui_story_5041_50410501_42_dialog_content = "\"¡La propensión a convencer a otros de correr alrededor del mundo con él!\"",
  ui_story_5041_50410501_43_dialog_content = "Bueno, eso es un hecho.",
  ui_story_5041_50410501_44_dialog_content = "\"Si no tienes cuidado, olvidarás lo que estabas destinado a hacer y pronto te encontrarás resolviendo una crisis en alguna parte\".",
  ui_story_5041_50410501_45_dialog_content = "\"¡Así que ten cuidado!\"",
  ui_story_5041_50410501_46_dialog_content = "Él no te llamó un chico malo, PlayerName!",
  ui_story_5041_50410501_47_dialog_content = "Estoy feliz por eso, pero...",
  ui_story_5041_50410501_48_dialog_content = "Eso todavía no me sienta muy bien de alguna manera...",
  ui_story_5041_50410601_1_dialog_content = "¡Paquete exprés para que firme, señorita Azure!",
  ui_story_5041_50410601_2_dialog_content = "PlayerName? ¿Eres el mensajero esta vez?",
  ui_story_5041_50410601_3_dialog_content = "A menudo estás rodeado de gente tan interesante.",
  ui_story_5041_50410601_4_dialog_content = "¡A-Muy bien, sin burlas, por favor!",
  ui_story_5041_50410601_5_dialog_content = "Esto es de Zeta.",
  ui_story_5041_50410601_6_dialog_content = "Esa niña se veía bastante imponente mientras dejaba el paquete.",
  ui_story_5041_50410601_7_dialog_content = "Ella dijo-",
  ui_story_5041_50410601_8_dialog_content = "¡Viejos mensajeros que cabalgaban sobre el dragón blanco, el guerrero solitario de las dunas os confía una misión!",
  ui_story_5041_50410601_9_dialog_content = "Entrégale esto al señor demonio azul que habita el Reino del Fuego.",
  ui_story_5041_50410601_10_dialog_content = "¡Como un mensaje de determinación de un guerrero!",
  ui_story_5041_50410601_11_dialog_content = "Supongo que eres el señor de los demonios azules del que habló.",
  ui_story_5041_50410601_12_dialog_content = "¿Un señor demonio otra vez? Ese parece ser mi papel permanente en su cabeza.",
  ui_story_5041_50410601_13_dialog_content = "Bueno, esta vez tenía que llegar.",
  ui_story_5041_50410601_14_dialog_content = "\"Esta vez\"? ¿Por qué no pareces nada sorprendido?",
  ui_story_5041_50410601_15_dialog_content = "Vamos a empezar desde el principio.",
  ui_story_5041_50410601_16_dialog_content = "Desde esa carrera de autos, Zeta se ha metido a desafiarme.",
  ui_story_5041_50410601_17_dialog_content = "Ella me desafía en diferentes cosas casi cada diez días más o menos.",
  ui_story_5041_50410601_18_dialog_content = "Cosas como piedra, papel o tijera, carreras, juegos de acción, etc.",
  ui_story_5041_50410601_19_dialog_content = "Pero ella nunca ha ganado.",
  ui_story_5041_50410601_20_dialog_content = "Eso suena como mucho...",
  ui_story_5041_50410601_21_dialog_content = "Jugar con una chica interesante como ella también es divertido para mí.",
  ui_story_5041_50410601_22_dialog_content = "De todos modos, ¡firme por el paquete!",
  ui_story_5041_50410601_23_dialog_content = "Seguro. Me pregunto a qué me está desafiando esta vez.",
  ui_story_5041_50410601_24_dialog_content = "<color=#e8d9bb>*Rotura*</color>",
  ui_story_5041_50410601_25_dialog_content = "¿Un pato?",
  ui_story_5041_50410601_26_dialog_content = "Esto es nuevo. Pero, ¿dónde está el desafío?",
  ui_story_5041_50410601_27_dialog_content = "Creo recordar algo.",
  ui_story_5041_50410601_28_dialog_content = "El pato es una grabadora. Roy usó uno para grabar la canción de Regina antes.",
  ui_story_5041_50410601_29_dialog_content = "Déjeme ver. Presiona aquí, creo.",
  ui_story_5041_50410601_30_dialog_content = "<color=#e8d9bb>Clic.</color>",
  ui_story_5041_50410601_31_dialog_content = "¡El viejo señor demonio azul del Reino del Fuego, el guerrero solitario de las dunas, te desafía!",
  ui_story_5041_50410601_32_dialog_content = "Demostraré mi resolución inquebrantable por la paz mundial y la libertad de todos los aurorianos.",
  ui_story_5041_50410601_33_dialog_content = "El tema de este desafío será: ¡Rock de heavy metal!",
  ui_story_5041_50410601_34_dialog_content = "Regina, compañera guerrera de las dunas, será la jueza y tomará decisiones justas.",
  ui_story_5041_50410601_35_dialog_content = "Si pierdes, señor de los demonios, sufrirás un severo castigo...",
  ui_story_5041_50410601_36_dialog_content = "¡El bar no te servirá bebidas durante todo un mes!",
  ui_story_5041_50410601_37_dialog_content = "Sin embargo, si el guerrero pierde...",
  ui_story_5041_50410601_38_dialog_content = "¡Castigaré a mi patético yo al no consumir piruletas durante 30 días!",
  ui_story_5041_50410601_39_dialog_content = "El tiempo de la impugnación está fijado para cinco días después del envío de esta carta. ¡Prepárate para mí, señor de los demonios!",
  ui_story_5041_50410601_40_dialog_content = "Vaya, parece que tenemos un verdadero desafío esta vez...",
  ui_story_5041_50410601_41_dialog_content = "¿No eres bueno en metal rock, Azure?",
  ui_story_5041_50410601_42_dialog_content = "Oh no, estaba hablando del castigo.",
  ui_story_5041_50410601_43_dialog_content = "¿Un mes entero sin alcohol?",
  ui_story_5041_50410601_44_dialog_content = "¡Tengo que mostrarle a ese chico lo bueno que soy!"
}
return config
